import ffmpeg from 'ffmpeg-static';import {spawnSync} from 'node:child_process';import {mkdirSync,readFileSync} from 'node:fs';import {createHash} from 'node:crypto';import {resolve} from 'node:path';import {ProjectDB} from '@dream/project-db';import {AssetSchema} from '@dream/footage';
const folder=resolve('artifacts/fixtures');mkdirSync(folder,{recursive:true});const source=resolve(folder,'source.mp4');const generated=spawnSync(ffmpeg!,['-y','-f','lavfi','-i','testsrc2=size=1280x720:rate=30:duration=6','-f','lavfi','-i','sine=frequency=330:sample_rate=48000:duration=6','-vf','scale=in_color_matrix=bt601:out_color_matrix=bt709','-color_primaries','bt709','-color_trc','bt709','-colorspace','bt709','-c:v','libx264','-pix_fmt','yuv420p','-c:a','aac','-shortest',source],{windowsHide:true});if(generated.status!==0)throw new Error(generated.stderr.toString().slice(-2000));const db=new ProjectDB(resolve('artifacts/Smoke Project'),'Smoke Project');db.saveAsset(AssetSchema.parse({id:'a_fixture',filename:'Original test pattern',kind:'video',durationSec:6,fps:30,width:1280,height:720,hasAudio:true,originalPath:source,proxyPath:source,fingerprint:createHash('sha256').update(readFileSync(source)).digest('hex'),status:'ready',waveform:Array.from({length:256},(_,i)=>.4+Math.sin(i/8)*.3)}));if(!db.timeline().spine.length)db.apply([{type:'insert_clip',position:0,clip:{id:'c_fixture',assetId:'a_fixture',srcIn:0,srcOut:6,speed:1,audio:{gainDb:-12,fadeInSec:.01,fadeOutSec:.01,mute:false},reason:'Original generated smoke fixture'},reason:'Smoke fixture'},{type:'add_item',item:{id:'g_fixture',type:'overlay',start:{kind:'clip',clipId:'c_fixture',at:'start',offsetSec:0},durationSec:6,component:'lower_third',params:{text:'Dream · local rendering',x:.5,y:.8,fontSize:38},layer:1,reason:'Verify shared composition'},reason:'Smoke fixture'}],'Smoke fixture','fixture',db.head());db.close();console.log(folder);
